def findMin(nums):
    esquerda, direita = 0, len(nums) - 1
    while esquerda < direita:
        meio = (esquerda + direita) // 2
        if nums[meio] > nums[direita]:
            esquerda = meio + 1
        else:
            direita = meio
    return nums[esquerda]

def search(nums, target):
    l, r = 0, len(nums) - 1
    while l <= r:
        m = (l + r) // 2
        if nums[m] == target:
            return m
        if nums[l] <= nums[m]:
            if nums[l] <= target < nums[m]:
                r = m - 1
            else:
                l = m + 1
        else:
            if nums[m] < target <= nums[r]:
                l = m + 1
            else:
                r = m - 1
    return -1

def threeSum(nums):
