def pacificAtlantic(heights):
    if not heights:
        return []
    r, c = len(heights), len(heights[0])
    pac, atl = set(), set()
    def dfs(i, j, vis, prev):
        if i < 0 or i >= r or j < 0 or j >= c or (i,j) in vis or heights[i][j] < prev:
            return
        vis.add((i, j))
        for di, dj in [(0,1), (0,-1), (1,0), (-1,0)]:
            dfs(i + di, j + dj, vis, heights[i][j])
    for i in range(r):
        dfs(i, 0, pac, heights[i][0])
        dfs(i, c-1, atl, heights[i][c-1])
    for j in range(c):
        dfs(0, j, pac, heights[0][j])
        dfs(r-1, j, atl, heights[r-1][j])
    return [list(x) for x in pac & atl]

def canFinish(numCourses, prerequisites):
    g = [[] for _ in range(numCourses)]
    d = [0] * numCourses
    for a, b in prerequisites:
        g[b].append(a)
        d[a] += 1
    q = [i for i in range(numCourses) if d[i] == 0]
    for i in q:
        for j in g[i]:
            d[j] -= 1
            if d[j] == 0:
                q.append(j)
    return len(q) == numCourses

