def alienOrder(words):
    from collections import defaultdict, deque
    g = defaultdict(set)
    d = {c: 0 for w in words for c in w}
    for i in range(len(words) - 1):
        for c1, c2 in zip(words[i], words[i+1]):
            if c1 != c2:
                if c2 not in g[c1]:
                    g[c1].add(c2)
                    d[c2] += 1
                break
    q = deque([c for c in d if d[c] == 0])
    r = []
    while q:
        c = q.popleft()
        r.append(c)
        for n in g[c]:
            d[n] -= 1
            if d[n] == 0:
                q.append(n)
    return ''.join(r) if len(r) == len(d) else ''

def ladderLength(bw, ew, wl):
    from collections import deque
    if ew not in wl:
        return 0
    wl = set(wl)
    q = deque([(bw, 1)])
    while q:
        w, l = q.popleft()
        if w == ew:
            return l
        for i in range(len(w)):
            for c in 'abcdefghijklmnopqrstuvwxyz':
                nw = w[:i] + c + w[i+1:]
                if nw in wl:
                    wl.remove(nw)
                    q.append((nw, l + 1))
    return 0

