def spiralOrder(matrix):
    if not matrix:
        return []
    r, c = len(matrix), len(matrix[0])
    topo, base = 0, r - 1
    esq, dir = 0, c - 1
    res = []
    while topo <= base and esq <= dir:
        for j in range(esq, dir + 1):
            res.append(matrix[topo][j])
        topo += 1
        for i in range(topo, base + 1):
            res.append(matrix[i][dir])
        dir -= 1
        if topo <= base:
            for j in range(dir, esq - 1, -1):
                res.append(matrix[base][j])
            base -= 1
        if esq <= dir:
            for i in range(base, topo - 1, -1):
                res.append(matrix[i][esq])
            esq += 1
    return res

