def minWindow(s, t):
    from collections import Counter
    need = Counter(t)
    missing = len(t)
    inicio = fim = i = 0
    for j, c in enumerate(s, 1):
        missing -= need[c] > 0
        need[c] -= 1
        if not missing:
            while i < j and need[s[i]] < 0:
                need[s[i]] += 1
                i += 1
            if not fim or j - i <= fim - inicio:
